import subprocess, os, tempfile

def handle(query, state):
    flag = state.get("flag", "")
    flag_file = os.path.join(tempfile.gettempdir(), "secret.conf")
    with open(flag_file, "w") as f:
        f.write(flag)
    hostname = (query.get("host") or [""])[0]
    if not hostname:
        return 200, {"Content-Type": "text/plain"}, "Usage: ?host=<hostname>"
    try:
        result = subprocess.check_output(
            f"nslookup {hostname}",
            shell=True,
            stderr=subprocess.STDOUT,
            timeout=5
        )
        return 200, {"Content-Type": "text/plain"}, result.decode("utf-8", errors="replace")
    except subprocess.CalledProcessError as e:
        output = e.output.decode("utf-8", errors="replace")
        if "NXDOMAIN" in output or "can't find" in output:
            return 200, {"Content-Type": "text/plain"}, "Host not found"
        return 200, {"Content-Type": "text/plain"}, output
    except Exception as e:
        return 500, {"Content-Type": "text/plain"}, str(e)
